struct User { var name: String }
let path: WritableKeyPath<User, String> = \.name
var user = User(name: "Mina")
user[keyPath: path] = "Jake"
print(user.name)

struct Pet { var name = "Coco" }
@dynamicMemberLookup struct Box {
    var pet = Pet()
    subscript<T>(dynamicMember p: KeyPath<Pet, T>)
        -> T { pet[keyPath: p] } }
print(Box().name)

